,[42.456769,0.121967],[42.456679,0.122042],[42.456549,0.122091],[42.456408,0.122211],[42.456272,0.122354],[42.45616,0.122509],[42.456048,0.122664],[42.455915,0.122889],[42.455835,0.123042],[42.455733,0.12322],[42.4557,0.12337],[42.455721,0.123623],[42.455735,0.1238],[42.455716,0.124065],[42.455763,0.124273],[42.455816,0.124514],[42.455845,0.124763],[42.455883,0.125032],[42.455928,0.125295],[42.455938,0.125559],[42.455975,0.125825],[42.456038,0.126069],[42.45607,0.126324],[42.456048,0.126579],[42.455956,0.126795],[42.455831,0.126994],[42.455692,0.127175],[42.455562,0.12737],[42.455416,0.127546],[42.455239,0.127688],[42.45507,0.127828],[42.454914,0.127988],[42.454768,0.128166],[42.45464,0.128369],[42.454517,0.128579],[42.454394,0.128776],[42.454244,0.128948],[42.454083,0.129099],[42.453928,0.129271],[42.4538,0.129475],[42.453687,0.129688],[42.453599,0.129921],[42.453513,0.130157],[42.453445,0.130408],[42.453376,0.130652],[42.453309,0.130899],[42.453225,0.131127],[42.453156,0.13138],[42.453072,0.131601],[42.452969,0.131826],[42.452922,0.131915],[42.452806,0.131932],[42.45269,0.131948],[42.452587,0.132005],[42.452401,0.132122],[42.452278,0.132157],[42.452154,0.132191],[42.452046,0.13234],[42.451938,0.132488],[42.45183,0.132636],[42.451735,0.132773],[42.451641,0.13291],[42.451539,0.13307],[42.451457,0.133199],[42.451438,0.133229],[42.45134,0.13339],[42.451309,0.133682],[42.451277,0.133974]]$coords$::jsonb;
  v_landmarks jsonb := $landmarks$[[42.417752,0.138558],[42.451277,0.133974]]$landmarks$::jsonb;
  v_route record;
  v_points jsonb;
  v_count integer;
  v_length_km double precision;
  v_max_gap_km double precision;
  v_center_gap_km double precision;
  v_invalid integer;
  v_start_gap_m double precision;
  v_end_gap_m double precision;
  v_closing_gap_m double precision;
  v_landmark_gap_m double precision;
begin
  select jsonb_agg(jsonb_build_object(
    'lat',(point->>0)::double precision,
    'lon',(point->>1)::double precision
  ) order by ordinality)
    into v_points
    from jsonb_array_elements(v_coords)
      with ordinality as p(point,ordinality);
  select h.id,h.latitude,h.longitude,h.published,h.trace_available,
      h.official_url,h.description,h.distance_km,h.route_type,
      h.duration_minutes,h.ascent_m,
      t.status,t.segments,t.geometry_source,t.geometry_source_url,
      t.official,t.continuity_checked,t.checked_at
    into v_route
    from public.hiking_routes h
    join public.hiking_route_tracks t on t.route_id=h.id
    where h.id='osm-relation-9672492'
      and h.source='openstreetmap' and h.source_type='relation'
      and h.external_id=9672492
      and h.name='Aínsa - San Vicente de Labuerda - Labuerda'
      and h.route_ref='PR-HU 41' and h.raw_tags->>'ref'='PR-HU 41'
      and h.source_url='https://www.openstreetmap.org/relation/9672492'
      and (h.official_url is not distinct from null
        or h.official_url='https://misendafedme.es/buscador-de-senderos/etapa/pr-hu-41-ainsa-labuerda')
      and h.region_code='huesca' and h.province='Huesca'
      and h.latitude=42.4437197 and h.longitude=0.1166594
      and exists (select 1 from public.hiking_route_regions r
        where r.route_id=h.id and r.region_code='huesca' and r.published)
    for update of h,t;
  if not found then
    raise exception 'PR-HU 41 route identity or published region changed';
  end if;
  if v_route.status='ready' then
    if v_route.geometry_source_url='https://misendafedme.es/buscador-de-senderos/inc/downloadGpx.php?etapa=117647'
      and v_route.geometry_source='FEDME - GPX oficial PR-HU 41'
      and v_route.segments=jsonb_build_array(v_points)
      and v_route.official and v_route.continuity_checked
      and v_route.checked_at is not null
      and v_route.published and v_route.trace_available
      and v_route.official_url='https://misendafedme.es/buscador-de-senderos/etapa/pr-hu-41-ainsa-labuerda'
      and v_route.distance_km=11.83
      and v_route.route_type='Lineal'
      and v_route.duration_minutes is null
      and v_route.ascent_m is null
      and v_route.description='PR-HU 41 de Aínsa a Labuerda, pasando por San Vicente de Labuerda. El GPX oficial contiene el recorrido lineal de ida: 11,83 km.' then
      return;
    end if;
    raise exception 'PR-HU 41 route has another ready trace or publication state';
  end if;
  if v_route.status is distinct from 'missing'
    or v_route.published is distinct from false
    or v_route.trace_available is distinct from false
    or v_route.segments is not null or v_route.geometry_source_url is not null
    or v_route.geometry_source is distinct from 'OpenStreetMap'
    or v_route.official is distinct from false
    or v_route.continuity_checked is distinct from true
    or v_route.official_url is distinct from null
    or v_route.description is distinct from null
    or v_route.distance_km is distinct from 12
    or v_route.ascent_m is not null or v_route.duration_minutes is not null
    or v_route.route_type is distinct from null then
    raise exception 'PR-HU 41 hidden route state changed';
  end if;
  with points as (
    select ordinality idx,(point->>0)::double precision lat,
      (point->>1)::double precision lon
    from jsonb_array_elements(v_coords) with ordinality as p(point,ordinality)
  ), steps as (
    select *,lag(lat) over(order by idx) prev_lat,
      lag(lon) over(order by idx) prev_lon from points
  ), distances as (
    select case when prev_lat is null then 0 else
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(prev_lon,prev_lat))/1000 end step_km,
      ST_DistanceSphere(ST_MakePoint(lon,lat),
        ST_MakePoint(v_route.longitude,v_route.latitude))/1000 center_km,
      (lat between 42.41 and 42.47 and lon between 0.09 and 0.14) valid
    from steps
  )
  select count(*),coalesce(sum(step_km),0),coalesce(max(step_km),0),
    coalesce(min(center_km),999),count(*) filter(where not valid)
    into v_count,v_length_km,v_max_gap_km,v_center_gap_km,v_invalid
    from distances;
  select ST_DistanceSphere(
    ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
    ST_MakePoint(0.138558,42.417752)),
    ST_DistanceSphere(
    ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
      (v_coords->(v_count-1)->>0)::double precision),
    ST_MakePoint(0.133974,42.451277)),
    ST_DistanceSphere(
    ST_MakePoint((v_coords->0->>1)::double precision,(v_coords->0->>0)::double precision),
    ST_MakePoint((v_coords->(v_count-1)->>1)::double precision,
      (v_coords->(v_count-1)->>0)::double precision))
    into v_start_gap_m,v_end_gap_m,v_closing_gap_m;
  select max(nearest.gap_m) into v_landmark_gap_m
    from jsonb_array_elements(v_landmarks) as w(landmark)
    cross join lateral (
      select min(ST_DistanceSphere(
        ST_MakePoint((point->>1)::double precision,(point->>0)::double precision),
        ST_MakePoint((w.landmark->>1)::double precision,(w.landmark->>0)::double precision))) gap_m
      from jsonb_array_elements(v_coords) as p(point)
    ) nearest;
  if v_count<>741 or v_invalid>0
    or abs(v_length_km-11.834831)>0.015
    or v_max_gap_km>0.026 or v_center_gap_km>0.6
    or v_start_gap_m>2 or v_end_gap_m>2 or v_closing_gap_m<500
    or v_landmark_gap_m>10 then
    raise exception 'PR-HU 41 GPS validation failed: points %, length %, gap %, center %, start %, end %, closure %, landmarks %, invalid %',
      v_count,v_length_km,v_max_gap_km,v_center_gap_km,
      v_start_gap_m,v_end_gap_m,v_closing_gap_m,v_landmark_gap_m,v_invalid;
  end if;
  update public.hiking_route_tracks
    set status='ready',segments=jsonb_build_array(v_points),checked_at=now(),
      continuity_checked=true,geometry_source='FEDME - GPX oficial PR-HU 41',
      geometry_source_url='https://misendafedme.es/buscador-de-senderos/inc/downloadGpx.php?etapa=117647',official=true
    where route_id=v_route.id and status='missing';
  if not found then
    raise exception 'PR-HU 41 track state changed';
  end if;
  update public.hiking_routes
    set trace_available=true,published=true,
      distance_km=round(v_length_km::numeric,2),route_type='Lineal',
      official_url='https://misendafedme.es/buscador-de-senderos/etapa/pr-hu-41-ainsa-labuerda',description='PR-HU 41 de Aínsa a Labuerda, pasando por San Vicente de Labuerda. El GPX oficial contiene el recorrido lineal de ida: 11,83 km.'
    where id=v_route.id and not published and not trace_available;
  if not found then
    raise exception 'PR-HU 41 publication state changed';
  end if;
end
$curate$;
